INSERT INTO cms.article (id, slug, title_en, title_ar, excerpt_en, excerpt_ar, body_en, body_ar, body_html_en, body_html_ar, cover_url, seo_title_en, seo_title_ar, seo_description_en, seo_description_ar, category, tags, author_name, status, publish_at, featured, created_at, updated_at) VALUES ('art-11', 'saffron-table-sustainability-pledge', 'Practical Sustainability Targets for Bahrain Operations in 2026', 'مستهدفات الاستدامة العملية للعمليات في البحرين 2026', 'Key operational benchmarks, real metrics, and 2026 guidance from Saffron Table in Adliya.', 'أبرز المعايير التشغيلية والأرقام الموثقة وإرشادات 2026 من مائدة الزعفران في Adliya.', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Contemporary Bahraini kitchen and gourmet pantry crafting daily fresh dishes, specialty spice blends, and corporate catering. Focusing on Corporate Buffet Catering (50 Guests), our teams help Gulf enterprises scale reliably."}]}]}'::jsonb, '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"مطبخ بحريني معاصر ومتجر منتجات غذائية يقدم أطباقاً طازجة يومياً وخلطات توابل فاخرة وضيافة للشركات. من خلال خدمة ضيافة بوفيه للشركات (50 ضيفاً) نساعد المؤسسات على النمو المستدام."}]}]}'::jsonb, '<p>Contemporary Bahraini kitchen and gourmet pantry crafting daily fresh dishes, specialty spice blends, and corporate catering.</p><p>Focusing on <strong>Corporate Buffet Catering (50 Guests)</strong>, our Adliya specialists help Gulf organizations standardize turnaround times and audit transparency.</p>', '<p>مطبخ بحريني معاصر ومتجر منتجات غذائية يقدم أطباقاً طازجة يومياً وخلطات توابل فاخرة وضيافة للشركات.</p><p>من خلال خدمة <strong>ضيافة بوفيه للشركات (50 ضيفاً)</strong>، يعمل فريقنا في Adliya على توحيد سرعة التسليم ووضوح التدقيق.</p>', '/api/files/media/banners/banner-02.png', 'Practical Sustainability Targets for Bahrain Operations in 2026 | Saffron Table', 'مستهدفات الاستدامة العملية للعمليات في البحرين 2026 | مائدة الزعفران', 'Executive guide by Saffron Table covering Corporate Buffet Catering (50 Guests) benchmarks in Bahrain.', 'دليل تنفيذي من مائدة الزعفران حول معايير ضيافة بوفيه للشركات (50 ضيفاً) في البحرين.', 'Sustainability', '{"food","sustainability","Adliya","2026"}'::text[], 'Hana Yousef', 'published', now() - interval '66 days', false, now() - interval '66 days', now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO cms.faq (id, question_en, question_ar, answer_en, answer_ar, category, is_published, sort_order, created_at) VALUES ('faq-11', 'Can scope adjustments be added mid-project cleanly?', 'هل يمكن إضافة أو تعديل نطاق العمل أثناء تنفيذ المشروع؟', 'Any variation order generates a transparent delta quotation linked directly to the parent project and budget.', 'يتم إصدار ملحق تعديل واضح مرتبط مباشرة بميزانية المشروع الأساسية وموافقتكم.', 'changes', true, 11, now() - interval '45 days') ON CONFLICT (id) DO NOTHING;
