INSERT INTO workflow.letter_template (id, name_en, name_ar, template_body, sort_order) VALUES ('ltmp-02', 'Executive Employment Verification', 'شهادة تعريف بالراتب والعمل', 'To Whom It May Concern: This certifies that {{recipient}} is employed full-time with {{company}} in Bahrain.', 2) ON CONFLICT (id) DO NOTHING;
